commands.command:
set -eu
sudo tee /etc/named.conf >/dev/null <<'ANTRIEB_NAMED'
options {
    listen-on port 53 { 127.0.0.1; 10.100.160.10; };
    listen-on-v6 { none; };
    directory "/var/named";
    key-directory "/var/named/dynamic";
    recursion no;
    allow-query { any; };
    allow-transfer { none; };
    dnssec-validation no;
    minimal-responses yes;
};

include "/etc/named/infra-update.key";

zone "infra.test" IN {
    type master;
    file "dynamic/infra.test";
    dnssec-policy default;
    inline-signing yes;
    allow-update { key "infra-update"; };
    allow-transfer { 10.100.160.11; 10.100.160.12; };
    also-notify { 10.100.160.11; 10.100.160.12; };
    notify yes;
};
ANTRIEB_NAMED
sudo chown root:named /etc/named.conf
sudo chmod 0640 /etc/named.conf
sudo restorecon /etc/named.conf
sudo named-checkconf -z /etc/named.conf

